        /// <summary>
        /// Dictionary that holds the colors used in the editor
        /// (CAN'T BE MADE PRIVATE, DON'T LISTEN TO THE IDE)
        /// </summary>
        public static readonly Dictionary<C_ID, Color> ColorDictionary = InitializeColors();
        /// <summary>
        /// Returns a dictionary of ID - Color pairs that are used in the editor windows
        /// </summary>
        /// <returns></returns>
        private static Dictionary<C_ID, Color> InitializeColors()
        {
            var temp = new Dictionary<C_ID, Color>();

            // if dark theme
            if (EditorGUIUtility.isProSkin)
            {
                temp.Add(C_ID.c_toolbarBackgroundColor, new Color(60f / 255f, 60f / 255f, 60f / 255f));
                temp.Add(C_ID.c_highlightColor, new Color(168f / 255f, 168f / 255f, 168f / 255f));
                temp.Add(C_ID.c_toolbarDividerColor, new Color(88f / 255f, 88f / 255f, 88f / 255f));
            }
            // if light theme
            else
            {
                temp.Add(C_ID.c_backgroundColor, new Color(160f / 255f, 160f / 255f, 160f / 255f));
                temp.Add(C_ID.c_fieldBoxColor, new Color(180f / 255f, 180f / 255f, 180f / 255f));
                temp.Add(C_ID.c_windowBorderColor, new Color(200f / 255f, 200f / 255f, 200f / 255f));
            }
            
            // grid
            temp.Add(C_ID.c_windowBorderColor, new Color(60f / 255f, 60f / 255f, 60f / 255f));
            temp.Add(C_ID.c_fieldBoxColor, new Color(50f / 255f, 50f / 255f, 50f / 255f));
            temp.Add(C_ID.c_backgroundColor, new Color(40f / 255f, 40f / 255f, 40f / 255f));
            temp.Add(C_ID.lineColor, new Color(81f / 255f, 81f / 255f, 81f / 255f));
            temp.Add(C_ID.highlightColor, new Color(168f / 255f, 168f / 255f, 168f / 255f));
            temp.Add(C_ID.selectedColor, new Color(40f / 255f, 168f / 255f, 168f / 255f));
            temp.Add(C_ID.clipboardColor, new Color(40f / 255f, 168f / 255f, 40f / 255f));
            temp.Add(C_ID.inspectingColor, new Color(1f, 1f, 40f / 255f));
            temp.Add(C_ID.modifiedColor, new Color(1f, 210f / 255f, 1f));
            temp.Add(C_ID.modifiedDarkColor, new Color(.25f, 40f / 255f, .25f));
            temp.Add(C_ID.presetBlockColor, new Color(255 / 255f, 147 / 255f, 15 / 255f));
            
            return temp;
        }
        
        
